namespace sv_2cfdec9271894335947b4ba5affeba62;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

@rendermode InteractiveServer

<span class="badge rounded-pill"
      style="background-color: @(Theme?.AccentColor ?? "#0d6efd");">
    @ThemeLabel
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string ThemeLabel => Theme?.Theme switch
    {
        Theme.Dark => "🌙 Dark",
        Theme.System => "💻 System",
        _ => "☀️ Light"
    };
}

@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<div class="nav-item px-3 py-2">
    <button class="btn btn-sm w-100"
            style="background-color: @(Theme?.AccentColor ?? "#0d6efd"); color: white;"
            @onclick="CycleTheme">
        @ButtonLabel
    </button>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string ButtonLabel => Theme?.Theme switch
    {
        Theme.Dark => "🌙 Dark Mode",
        Theme.System => "💻 System Mode",
        _ => "☀️ Light Mode"
    };

    private async Task CycleTheme()
    {
        var current = Theme?.Theme ?? Theme.Light;
        var next = current switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };

        var updated = new ThemeInfo
        {
            Theme = next,
            AccentColor = Theme?.AccentColor ?? "#0d6efd"
        };
        await ThemeSource.NotifyChangedAsync(updated);
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Color mode</label>
            <select class="form-select" value="@currentTheme" @onchange="OnThemeChanged">
                <option value="Light">☀️ Light</option>
                <option value="Dark">🌙 Dark</option>
                <option value="System">💻 System</option>
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color" class="form-control form-control-color"
                       value="@currentAccent" @onchange="OnAccentChanged" />
                <span class="text-muted">@currentAccent</span>
            </div>
        </div>

        <div class="alert alert-info mb-0">
            Changes apply immediately across the entire app.
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string currentTheme = nameof(Theme.Light);
    private string currentAccent = "#0d6efd";

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            currentTheme = Theme.Theme.ToString();
            currentAccent = Theme.AccentColor;
        }
    }

    private async Task OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var parsed))
        {
            var updated = new ThemeInfo
            {
                Theme = parsed,
                AccentColor = currentAccent
            };
            await ThemeSource.NotifyChangedAsync(updated);
        }
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        var color = e.Value?.ToString() ?? "#0d6efd";
        var updated = new ThemeInfo
        {
            Theme = Theme?.Theme ?? Theme.Light,
            AccentColor = color
        };
        await ThemeSource.NotifyChangedAsync(updated);
    }
}

